CREATE OR REPLACE VIEW pongit_history.matches_raw AS SELECT DISTINCT ON(id) "id","deployment","rawId","mode","ranked","rulesVersion","playerA","playerB","tournamentId","status","winner","played","scoreA","scoreB","endedAt","replayAvailability","block" FROM (SELECT "id","deployment","rawId","mode","ranked","rulesVersion","playerA","playerB","tournamentId","status","winner","played","scoreA","scoreB","endedAt","replayAvailability","block",1 AS source_priority FROM indexer."Match" UNION ALL SELECT "id","deployment","rawId","mode","ranked","rulesVersion","playerA","playerB","tournamentId","status","winner","played","scoreA","scoreB","endedAt","replayAvailability","block",2 AS source_priority FROM arcade_five_20260929."Match" UNION ALL SELECT "id","deployment","rawId","mode","ranked","rulesVersion","playerA","playerB","tournamentId","status","winner","played","scoreA","scoreB","endedAt","replayAvailability","block",3 AS source_priority FROM agents_live_20260929."Match" UNION ALL SELECT "id","deployment","rawId","mode","ranked","rulesVersion","playerA","playerB","tournamentId","status","winner","played","scoreA","scoreB","endedAt","replayAvailability","block",4 AS source_priority FROM agents_sync_20261003."Match" UNION ALL SELECT "id","deployment","rawId","mode","ranked","rulesVersion","playerA","playerB","tournamentId","status","winner","played","scoreA","scoreB","endedAt","replayAvailability","block",5 AS source_priority FROM human_v3_20261005."Match") AS all_matches ORDER BY id,block DESC,source_priority DESC;